import os
from collections import Counter

def count_words(directory):
    word_counts = Counter()
    for filename in os.listdir(directory):
        if filename.endswith(".txt"):
            with open(os.path.join(directory, filename), "r") as file:
                for line in file:
                    for word in line.split():
                        word_counts[word] += 1
    return word_counts

def get_top_words(word_counts, n=5):
    return sorted(word_counts.items(), key=lambda x: x[1], reverse=True)[:n]

if __name__ == "__main__":
    directory = "/path/to/directory"
    word_counts = count_words(directory)
    top_words = get_top_words(word_counts)
    print("Top-5 words with the most number of occurrences:")
    for word, count in top_words:
        print(f"{word}: {count}")
```

This program uses the `os` module to list all the files under a directory, and the `collections.Counter` class to count the number of occurrences of each word in the text files. The `count_words` function takes a directory path as input and returns a `Counter` object that maps each word to its count. The `get_top_words` function takes a `Counter` object and an optional `n` parameter (defaulting to 5) and returns a list of the `n` most frequent words in the `Counter`. Finally, the program prints out the top-5 words with the most number of occurrences.<|end_of_text|>

